-- Russian for story/story_*.lua; a missing key shows the English.

local T = {}

T["You find yourself walking through the quaint Fox Village in the forest."] = "Вы прогуливаетесь по уютной Лисьей деревне посреди леса."
T["It's a cloudy day, painting the town in a tone of gray."] = "День пасмурный, и весь городок окрашен в серые тона."
T["Suddenly, you hear footsteps coming your way, and an impact against you blows you to the ground!"] = "Вдруг вы слышите, как кто-то бежит в вашу сторону, -- и тут что-то врезается в вас и сбивает с ног!"
T["You open your eyes back up, and find a familiar looking young fox boy crying."] = "Открыв глаза, вы видите перед собой плачущего мальчика-лисёнка. Его лицо кажется вам знакомым."
T["Are you okay? What's wrong?"] = "Ты в порядке? Что случилось?"
T["Ow..."] = "Ай..."
T["HEY! I'M WALKING HERE!"] = "ЭЙ! СМОТРИ, КУДА ПРЁШЬ!"
T["Ah, I'm so sorry! I..."] = "Ой, прости, пожалуйста! Я..."
T["The boy pauses for a second, looking at you carefully."] = "Мальчик на секунду замирает и внимательно вас разглядывает."
T["You... {pause:0.4}\nYou're the one that's been visiting our dojo lately..."] = "Ты... {pause:0.4}\nЭто ведь ты в последнее время ходишь к нам в додзё..."
T["Ume?"] = "Умэ?"
