T["I'd be happy to!"] = "С удовольствием!"
T["That's why I'm here."] = "Я ведь за этим и здесь."
T["You nod."] = "Вы киваете."
T["Maybe another time."] = "Может, в другой раз."
T["Understood! Don't hesitate to come anytime..."] = "Понял! Приходи в любое время..."
